//! TLS against the pgtls service: PostgreSQL 19 with a private CA, client certificates and host-based rules.
//! Needs the test stack; the certificates are generated by the stack at first start and read back at test time.

mod common;

use std::io::{Read, Write};
use std::net::{TcpListener, TcpStream};
use std::path::PathBuf;
use std::process::{Child, Command, Stdio};
use std::sync::Arc;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::time::{Duration, Instant};

use common::PORT_TLS;
use postgres_mcp::pg::pool::{Pool, PoolError};
use postgres_mcp::pg::tls::{PemSource, SslMode, TlsSources, startup_client_config};
use postgres_mcp::pg::wire::{AuthPolicy, ConnectConfig, Connection, WireError};
use rustls::ClientConfig;
use serde_json::{Value, json};

const HOST: &str = "localhost";
const IP_HOST: &str = "127.0.0.1";
const DB: &str = "appdb";
const RO_USER: &str = "mcp_ro";
const RO_PASSWORD: &str = "test-only-ro";
const CERT_USER: &str = "mcp_cert";
const CERT_PASSWORD: &str = "test-only-cert";
const SUPER_USER: &str = "postgres";
const SUPER_PASSWORD: &str = "test-only-superuser";
const PROTOCOL: &str = "2025-11-25";

/// The PEM files the stack generated, copied into a temp directory that is removed on drop.
struct Material {
    dir: PathBuf,
}

impl Material {
    /// Reads each generated file through a superuser connection with sslmode=require.
    async fn fetch() -> Material {
        static COUNTER: AtomicUsize = AtomicUsize::new(0);
        let n = COUNTER.fetch_add(1, Ordering::SeqCst);
        let dir = std::env::temp_dir().join(format!("pgmcp-tls-real-{}-{n}", std::process::id()));
        std::fs::create_dir_all(&dir).expect("create the temp dir");
        let material = Material { dir };
        let mut conn = Connection::connect(&connect_cfg(
            IP_HOST,
            SUPER_USER,
            SUPER_PASSWORD,
            SslMode::Require,
            None,
        ))
        .await
        .expect("superuser connects with sslmode=require");
        for name in [
            "ca.crt",
            "bad_ca.crt",
            "client.crt",
            "client.key",
            "client_pkcs1.key",
            "client_ec.crt",
            "client_ec.key",
            "bad_client.crt",
            "bad_client.key",
        ] {
            let sql = format!("SELECT pg_read_file('tls/{name}')");
            let result = conn.simple_query(&sql).await.expect("pg_read_file");
            let text = result.rows[0][0].clone().expect("the file has content");
            std::fs::write(material.path(name), text).expect("write the PEM copy");
        }
        material
    }

    fn path(&self, name: &str) -> PathBuf {
        self.dir.join(name)
    }

    fn text(&self, name: &str) -> String {
        std::fs::read_to_string(self.path(name)).expect("read the PEM copy")
    }

    /// The PEM text with each newline written as a backslash and n, as an environment value carries it.
    fn escaped(&self, name: &str) -> String {
        self.text(name).replace('\n', "\\n")
    }
}

impl Drop for Material {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.dir);
    }
}

fn file(path: PathBuf) -> Option<PemSource> {
    Some(PemSource::File(path))
}

/// Sources with the test CA as the root and a client identity from files, or inline PEM when `inline` is set.
fn client_sources(m: &Material, cert: &str, key: &str, inline: bool) -> TlsSources {
    if inline {
        TlsSources {
            root: Some(PemSource::Inline(m.text("ca.crt"))),
            client_cert: Some(PemSource::Inline(m.text(cert))),
            client_key: Some(PemSource::Inline(m.text(key))),
        }
    } else {
        TlsSources {
            root: file(m.path("ca.crt")),
            client_cert: file(m.path(cert)),
            client_key: file(m.path(key)),
        }
    }
}

/// Prepared TLS for `mode` with the given sources; a failure here is a test failure.
fn tls_for(mode: SslMode, sources: TlsSources) -> Arc<ClientConfig> {
    startup_client_config(mode, &sources).unwrap_or_else(|e| panic!("TLS setup failed: {e}"))
}

fn connect_cfg(
    host: &str,
    user: &str,
    password: &str,
    mode: SslMode,
    root: Option<PathBuf>,
) -> ConnectConfig {
    ConnectConfig {
        host: host.into(),
        port: PORT_TLS,
        database: DB.into(),
        user: user.into(),
        password: Some(password.into()),
        ssl_mode: mode,
        ssl_root_cert: root,
        connect_timeout: Duration::from_secs(10),
        startup_params: Vec::new(),
    }
}

/// Opens one connection with the prepared TLS configuration, if any.
async fn open(
    cfg: &ConnectConfig,
    tls: Option<Arc<ClientConfig>>,
) -> Result<Connection, WireError> {
    Connection::connect_with_tls(cfg, &AuthPolicy::default(), tls).await
}

/// The backend's TLS state from pg_stat_ssl: (ssl, version, client_dn), with NULL shown as an empty string.
async fn tls_state(conn: &mut Connection) -> (String, String, String) {
    let sql = "SELECT ssl::text, coalesce(version, ''), coalesce(client_dn, '') \
               FROM pg_stat_ssl WHERE pid = pg_backend_pid()";
    let result = conn.simple_query(sql).await.expect("pg_stat_ssl row");
    let row = &result.rows[0];
    (
        row[0].clone().expect("ssl"),
        row[1].clone().expect("version"),
        row[2].clone().expect("client_dn"),
    )
}

/// The client-facing text of a failed pooled connect.
async fn pool_refusal(cfg: ConnectConfig, tls: Option<Arc<ClientConfig>>) -> PoolError {
    let pool = Pool::with_auth(cfg, 1, AuthPolicy::default())
        .with_tls(tls)
        .with_name("pgtls");
    match pool.checkout(Duration::from_secs(10)).await {
        Ok(_) => panic!("the connection was expected to be refused"),
        Err(error) => error,
    }
}

/// Connects as the certificate role and checks the TLS state, returning the connection state text.
async fn mcp_cert_connects(
    m: &Material,
    cert: &str,
    key: &str,
    inline: bool,
) -> (String, String, String) {
    let tls = tls_for(SslMode::VerifyFull, client_sources(m, cert, key, inline));
    let cfg = connect_cfg(
        HOST,
        CERT_USER,
        CERT_PASSWORD,
        SslMode::VerifyFull,
        Some(m.path("ca.crt")),
    );
    let mut conn = open(&cfg, Some(tls))
        .await
        .unwrap_or_else(|e| panic!("mcp_cert with {cert} and {key} is refused: {e}"));
    tls_state(&mut conn).await
}

#[tokio::test]
async fn verify_full_with_the_test_ca_file_connects_over_tls() {
    let m = Material::fetch().await;
    let root = m.path("ca.crt");
    let tls = tls_for(
        SslMode::VerifyFull,
        TlsSources {
            root: file(root.clone()),
            ..TlsSources::default()
        },
    );
    let cfg = connect_cfg(HOST, RO_USER, RO_PASSWORD, SslMode::VerifyFull, Some(root));
    let mut conn = open(&cfg, Some(tls)).await.expect("verify-full connects");
    let (ssl, version, client_dn) = tls_state(&mut conn).await;
    assert_eq!(ssl, "true");
    assert!(
        matches!(version.as_str(), "TLSv1.2" | "TLSv1.3"),
        "negotiated {version}"
    );
    assert_eq!(client_dn, "");
    let count = conn
        .simple_query("SELECT count(*) AS n FROM app.items")
        .await
        .expect("count");
    assert_eq!(count.rows[0][0].as_deref(), Some("3"));
}

