#[tokio::test]
async fn verify_full_with_an_unrelated_ca_fails_with_the_tls_error() {
    let m = Material::fetch().await;
    let tls = tls_for(
        SslMode::VerifyFull,
        TlsSources {
            root: file(m.path("bad_ca.crt")),
            ..TlsSources::default()
        },
    );
    let cfg = connect_cfg(
        HOST,
        RO_USER,
        RO_PASSWORD,
        SslMode::VerifyFull,
        Some(m.path("bad_ca.crt")),
    );
    let err = match open(&cfg, Some(tls)).await {
        Ok(_) => panic!("an unrelated CA must not verify"),
        Err(error) => error,
    };
    // The TLS error comes before the startup packet, so no password is sent.
    match err {
        WireError::Tls(message) => {
            assert_eq!(message, "invalid peer certificate: UnknownIssuer");
        }
        other => panic!("expected a TLS error, got {other:?}"),
    }
}

#[tokio::test]
async fn verify_full_to_an_ip_address_not_in_the_certificate_fails() {
    let m = Material::fetch().await;
    let tls = tls_for(
        SslMode::VerifyFull,
        TlsSources {
            root: file(m.path("ca.crt")),
            ..TlsSources::default()
        },
    );
    let cfg = connect_cfg(
        IP_HOST,
        RO_USER,
        RO_PASSWORD,
        SslMode::VerifyFull,
        Some(m.path("ca.crt")),
    );
    let err = match open(&cfg, Some(tls)).await {
        Ok(_) => panic!("the certificate lists no IP address"),
        Err(error) => error,
    };
    match err {
        WireError::Tls(message) => assert_eq!(
            message,
            "invalid peer certificate: certificate not valid for name \"127.0.0.1\"; certificate is only valid for DnsName(\"localhost\") or DnsName(\"pgtls.test.example\")"
        ),
        other => panic!("expected a TLS error, got {other:?}"),
    }
}

